import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Number of chunks each row is split into for the reduction/normalization
// pass.  Splitting the row across multiple thread blocks lets us launch a
// grid large enough to fill all SMs even when the batch dimension (N) is
// small, instead of launching only N blocks (one per row).
#define LN_CHUNKS 128
// ---------------------------------------------------------------------
// Pass 1 (vec4): each block computes a partial sum / sum-of-squares over
// a contiguous chunk of the (float4-viewed) row and atomically
// accumulates it into per-row global accumulators.
// ---------------------------------------------------------------------
__global__ void layernorm_reduce_vec4(
    const float* __restrict__ X,
    float* __restrict__ sum_arr,
    float* __restrict__ sumsq_arr,
    int M4, int chunks)
{
  int n = blockIdx.x;
  int c = blockIdx.y;
  // interleaved striding across chunks for balanced load
  const float4* x_row = reinterpret_cast<const float4*>(X + (int64_t)n * M4 * 4);
  float sum = 0.f, sumsq = 0.f;
  int stride = chunks * blockDim.x;
  for (int i = c * blockDim.x + threadIdx.x; i < M4; i += stride) {
    float4 v = x_row[i];
    sum   += v.x + v.y + v.z + v.w;
    sumsq += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
  }
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum   += __shfl_down_sync(0xffffffffu, sum, offset);
    sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
  }
  __shared__ float s_sum[32];
  __shared__ float s_sumsq[32];
  int lane = threadIdx.x & 31;
  int wid  = threadIdx.x >> 5;
  if (lane == 0) {
    s_sum[wid]   = sum;
    s_sumsq[wid] = sumsq;
  }
  __syncthreads();
  int numWarps = (blockDim.x + 31) >> 5;
  if (wid == 0) {
    sum   = (lane < numWarps) ? s_sum[lane]   : 0.f;
    sumsq = (lane < numWarps) ? s_sumsq[lane] : 0.f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum   += __shfl_down_sync(0xffffffffu, sum, offset);
      sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
    }
    if (lane == 0) {
      sum_arr[n * chunks + c]   = sum;
      sumsq_arr[n * chunks + c] = sumsq;
    }
  }
}
// ---------------------------------------------------------------------
// Pass 2 (vec4): using the fully-accumulated per-row sum / sum-of-squares
// each block normalizes its chunk of the row.
// ---------------------------------------------------------------------
__global__ void layernorm_normalize_vec4(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    const float* __restrict__ sum_arr,
    const float* __restrict__ sumsq_arr,
    int M4, int M, float eps, int chunks)
{
  int n = blockIdx.x;
  int c = blockIdx.y;
  // per-chunk range now computed via interleaved striding for load balance
  __shared__ float s_mean;
  __shared__ float s_inv_std;
  if (threadIdx.x == 0) {
    float total_sum = 0.f, total_sumsq = 0.f;
    const float* row_sum = sum_arr + (int64_t)n * chunks;
    const float* row_sumsq = sumsq_arr + (int64_t)n * chunks;
    for (int i = 0; i < chunks; ++i) {
      total_sum   += row_sum[i];
      total_sumsq += row_sumsq[i];
    }
    float mean_val = total_sum / (float)M;
    float var_val  = total_sumsq / (float)M - mean_val * mean_val;
    s_mean = mean_val;
    s_inv_std = rsqrtf(var_val + eps);
  }
  __syncthreads();
  float mean    = s_mean;
  float inv_std = s_inv_std;
  const float4* x_row = reinterpret_cast<const float4*>(X + (int64_t)n * M4 * 4);
  float4*       y_row = reinterpret_cast<float4*>(Y + (int64_t)n * M4 * 4);
  const float4* w_ptr = reinterpret_cast<const float4*>(W);
  const float4* b_ptr = reinterpret_cast<const float4*>(B);
  for (int i = c * blockDim.x + threadIdx.x; i < M4; i += chunks * blockDim.x) {
    float4 v = x_row[i];
    float4 w = w_ptr[i];
    float4 b = b_ptr[i];
    float4 out;
    out.x = (v.x - mean) * inv_std * w.x + b.x;
    out.y = (v.y - mean) * inv_std * w.y + b.y;
    out.z = (v.z - mean) * inv_std * w.z + b.z;
    out.w = (v.w - mean) * inv_std * w.w + b.w;
    y_row[i] = out;
  }
}
// ---------------------------------------------------------------------
// Scalar fallback kernel (works for any M), used when M is not
// divisible by 4.  Kept as a single-block-per-row implementation using
// CuTe tensors for indexing, identical to the original version.
// ---------------------------------------------------------------------
__global__ void layernorm_kernel_scalar(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int M, float eps)
{
  int n = blockIdx.x;
  const float* x_row = X + (int64_t)n * M;
  float*       y_row = Y + (int64_t)n * M;
  Tensor gX = make_tensor(make_gmem_ptr(x_row), make_shape(M), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(y_row), make_shape(M), make_stride(Int<1>{}));
  Tensor gW = make_tensor(make_gmem_ptr(W),     make_shape(M), make_stride(Int<1>{}));
  Tensor gB = make_tensor(make_gmem_ptr(B),     make_shape(M), make_stride(Int<1>{}));
  float sum = 0.f, sumsq = 0.f;
  for (int i = threadIdx.x; i < M; i += blockDim.x) {
    float v = gX(i);
    sum   += v;
    sumsq += v * v;
  }
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum   += __shfl_down_sync(0xffffffffu, sum, offset);
    sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
  }
  __shared__ float s_sum[32];
  __shared__ float s_sumsq[32];
  int lane = threadIdx.x & 31;
  int wid  = threadIdx.x >> 5;
  if (lane == 0) {
    s_sum[wid]   = sum;
    s_sumsq[wid] = sumsq;
  }
  __syncthreads();
  int numWarps = (blockDim.x + 31) >> 5;
  if (wid == 0) {
    sum   = (lane < numWarps) ? s_sum[lane]   : 0.f;
    sumsq = (lane < numWarps) ? s_sumsq[lane] : 0.f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum   += __shfl_down_sync(0xffffffffu, sum, offset);
      sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
    }
    if (lane == 0) {
      s_sum[0]   = sum;
      s_sumsq[0] = sumsq;
    }
  }
  __syncthreads();
  float mean    = s_sum[0] / (float)M;
  float var     = s_sumsq[0] / (float)M - mean * mean;
  float inv_std = rsqrtf(var + eps);
  for (int i = threadIdx.x; i < M; i += blockDim.x) {
    float v = gX(i);
    float w = gW(i);
    float b = gB(i);
    gY(i) = (v - mean) * inv_std * w + b;
  }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();
  int64_t M64 = 1;
  int64_t wdims = w_c.numel();
  M64 = wdims;
  int64_t total = x_c.numel();
  TORCH_CHECK(total % M64 == 0, "x size incompatible with normalized_shape");
  int64_t N64 = total / M64;
  int M = (int)M64;
  int N = (int)N64;
  auto y = torch::empty_like(x_c);
  const float* x_ptr = x_c.data_ptr<float>();
  const float* w_ptr = w_c.data_ptr<float>();
  const float* b_ptr = b_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (M % 4 == 0) {
    int M4 = M / 4;
    int chunks = LN_CHUNKS;
    // Avoid degenerate chunking when the row is tiny.
    if (chunks > M4) chunks = M4 > 0 ? M4 : 1;
    auto opts = x_c.options();
    auto sum_arr   = torch::empty({(int64_t)N * chunks}, opts);
    auto sumsq_arr = torch::empty({(int64_t)N * chunks}, opts);
    int threads = 256;
    dim3 grid(N, chunks);
    dim3 block(threads);
    layernorm_reduce_vec4<<<grid, block, 0, stream>>>(
        x_ptr, sum_arr.data_ptr<float>(), sumsq_arr.data_ptr<float>(), M4, chunks);
    layernorm_normalize_vec4<<<grid, block, 0, stream>>>(
        x_ptr, w_ptr, b_ptr, y_ptr,
        sum_arr.data_ptr<float>(), sumsq_arr.data_ptr<float>(),
        M4, M, (float)eps, chunks);
  } else {
    int threads = 512;
    dim3 grid(N);
    dim3 block(threads);
    layernorm_kernel_scalar<<<grid, block, 0, stream>>>(
        x_ptr, w_ptr, b_ptr, y_ptr, M, (float)eps);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include", "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single fused custom CUDA/CuTe kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight,
            self.bias,
            float(self.eps),
        )

